/**
 * @summary Get daily summary report
 */
export const GetDailyReportParams = zod.object({
  schoolId: zod.coerce.number(),
});

export const GetDailyReportQueryParams = zod.object({
  date: zod.date(),
});

export const GetDailyReportResponse = zod.object({
  date: zod.coerce.date(),
  schoolId: zod.number(),
  totalStudents: zod.number(),
  presentCount: zod.number(),
  absentCount: zod.number(),
  lateCount: zod.number(),
  attendanceRate: zod.number(),
  feesCollected: zod.number(),
  salesTotal: zod.number(),
  expenditureTotal: zod.number(),
  netCash: zod.number(),
  paymentDetails: zod.array(
    zod.object({
      id: zod.number(),
      schoolId: zod.number(),
      studentId: zod.number(),
      studentName: zod.string(),
      amount: zod.number(),
      paymentDate: zod.coerce.date(),
      paymentType: zod.enum(["school_fee", "bus_fee", "other"]),
      notes: zod.string().nullish(),
      createdAt: zod.coerce.date(),
    }),
  ),
});
